import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{r as t,o,c as p,d as i,e as n,a as d,w as c,f as a}from"./app-36705845.js";const l={},r=a(`<h1 id="别名分析-alias-analysis" tabindex="-1"><a class="header-anchor" href="#别名分析-alias-analysis" aria-hidden="true">#</a> 别名分析（Alias Analysis）</h1><p>指针分析对于可以任意访问指针和进行指针计算的语言（如C/C++等）具有重要意义。指针分析通过静态计算一个指针可能指向的对象，可以推断出非常多有用的信息。当然由于缺乏运行时信息，推断一般是<em>保守的</em>（即，结论是可能发生，而不是必然发生）。</p><p>对于指针分析，有两个重要的问题：</p><ol><li>指针的别名问题：即指针p和q是否可能指向同一个对象。</li><li>指针的指向问题：即指针p可能指向哪些对象。</li></ol><p>本节中我们就将主要讨论别名分析（Alias Analysis）。 别名分析的关键在于如何表示指针的别名关系。一般来说，有两种方式：</p><ol><li><strong>指针集合</strong>（Pointer Sets）：将每个指针表示为一个集合，集合中包含了指针可能指向的所有对象。这种方式的优点是简单直观，但是对于指针的别名关系的表示不够精确。</li><li><strong>别名图</strong>（Alias Graph）：将每个指针表示为一个节点，如果两个指针可能指向同一个对象，则在它们之间连一条边。这种方式的优点是可以精确地表示别名关系，但是图的构建和分析比较复杂。</li></ol><h2 id="别名分析的应用" tabindex="-1"><a class="header-anchor" href="#别名分析的应用" aria-hidden="true">#</a> 别名分析的应用</h2><p>别名分析在编译器优化中有着重要的应用，例如：</p><ol><li>冗余代码消除（Dead Code Elimination）：如果一个指针p在某个位置被赋值为NULL，那么在这之后所有通过p访问的对象都是无效的，可以被消除。</li><li>冗余加载消除（Load Elimination）：如果一个指针p在某个位置被赋值为q，那么在这之后所有通过p访问的对象都可以被替换为q。</li><li>冗余存储消除（Store Elimination）：如果一个指针p在某个位置被赋值为q，那么在这之后所有通过p访问的对象的存储可以被替换为q。</li><li>循环不变代码外提（Loop Invariant Code Motion）：如果一个指针p在循环内部没有被修改，那么可以将p的加载提到循环外部。</li></ol><p>这些优化都需要依靠准确的别名分析结果。</p><h2 id="指针和内存的表示方法" tabindex="-1"><a class="header-anchor" href="#指针和内存的表示方法" aria-hidden="true">#</a> 指针和内存的表示方法</h2><p>在别名分析中，我们需要对指针和内存进行抽象表示。一般来说，有这样几种方式：</p><ol><li><strong>内存对象</strong>（Memory Object）：将内存抽象为一个对象，对象包含了内存的地址和大小。这种方式的优点是简单直观，但是对于内存的精确表示不够。</li><li><strong>内存区域</strong>（Memory Region）：将内存抽象为一个区域，区域包含了内存的地址、大小和类型等信息。这种方式的优点是可以精确地表示内存的属性，但是对于内存的抽象和分析比较复杂。</li><li><strong>内存单元</strong>（Memory Unit）：将内存抽象为一个单元，单元包含了内存的地址、大小和类型等信息。这种方式的优点是可以精确地表示内存的属性，但是对于内存的抽象和分析比较复杂。</li></ol><p>分配和释放内存也是我们需要考虑的关键事件。</p><h2 id="基于指针集合的别名分析" tabindex="-1"><a class="header-anchor" href="#基于指针集合的别名分析" aria-hidden="true">#</a> 基于指针集合的别名分析</h2><p>指针集合是一种简单直观的别名分析表示方式。在这种方式中，每个指针都表示为一个集合，集合中包含了指针可能指向的所有对象。 为了简单起见，我们先考虑单个函数内，只有局部变量的情况。例如，对于下面的代码：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> <span class="token operator">*</span>p<span class="token punctuation">,</span> <span class="token operator">*</span>q<span class="token punctuation">;</span>
<span class="token keyword">int</span> a<span class="token punctuation">,</span> b<span class="token punctuation">;</span>
p <span class="token operator">=</span> <span class="token operator">&amp;</span>a<span class="token punctuation">;</span>
q <span class="token operator">=</span> <span class="token operator">&amp;</span>b<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>我们可以得到如下的指针集合：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>p -&gt; {a}
q -&gt; {b}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>此时 <code>p</code> 和 <code>q</code> 的集合没有交集，可以判定 <strong>p 与 q 不别名（NoAlias）</strong>。</p><p>遇到赋值语句时，按以下规则更新集合：</p><table><thead><tr><th>语句</th><th>更新规则</th></tr></thead><tbody><tr><td><code>p = &amp;x</code></td><td><code>pt(p) = {x}</code></td></tr><tr><td><code>p = q</code></td><td><code>pt(p) = pt(q)</code></td></tr><tr><td><code>p = NULL</code></td><td><code>pt(p) = ∅</code></td></tr></tbody></table><p>再看一个稍复杂的例子：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> <span class="token operator">*</span>p<span class="token punctuation">,</span> <span class="token operator">*</span>q<span class="token punctuation">,</span> <span class="token operator">*</span>r<span class="token punctuation">;</span>
<span class="token keyword">int</span> a<span class="token punctuation">,</span> b<span class="token punctuation">;</span>
p <span class="token operator">=</span> <span class="token operator">&amp;</span>a<span class="token punctuation">;</span>
q <span class="token operator">=</span> p<span class="token punctuation">;</span>      <span class="token comment">// q 抄了 p 的花名册</span>
r <span class="token operator">=</span> <span class="token operator">&amp;</span>b<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>更新后：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>p -&gt; {a}
q -&gt; {a}    // 与 p 相同
r -&gt; {b}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>此时 <code>p</code> 与 <code>q</code> 的集合都是 <code>{a}</code>，交集非空，判定为 <strong>一定别名（MustAlias）</strong>——它们指向同一对象 <code>a</code>。而 <code>p</code> 与 <code>r</code> 仍是不别名。</p><p>如果存在分支，集合就要取并集：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">if</span> <span class="token punctuation">(</span>cond<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    p <span class="token operator">=</span> <span class="token operator">&amp;</span>a<span class="token punctuation">;</span>
<span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
    p <span class="token operator">=</span> <span class="token operator">&amp;</span>b<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 汇合点：pt(p) = {a, b}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>汇合点之后，<code>p</code> 可能指向 <code>a</code> 也可能指向 <code>b</code>。此时若 <code>q = &amp;a</code>，则 <code>pt(p) ∩ pt(q) = {a} ≠ ∅</code>，p 与 q 为 MayAlias。</p><h3 id="三种别名关系" tabindex="-1"><a class="header-anchor" href="#三种别名关系" aria-hidden="true">#</a> 三种别名关系</h3><p>别名分析的结果通常分为三类：</p><table><thead><tr><th>关系</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><strong>MustAlias</strong></td><td>两点上两指针一定指向同一对象</td><td><code>q = p</code> 之后，<code>p</code> 与 <code>q</code></td></tr><tr><td><strong>MayAlias</strong></td><td>可能指向同一对象，也可能不</td><td>分支汇合后的 <code>p</code> 与 <code>&amp;a</code></td></tr><tr><td><strong>NoAlias</strong></td><td>一定不指向同一对象</td><td><code>p -&gt; {a}</code>, <code>q -&gt; {b}</code></td></tr></tbody></table><p>编译器优化时，<strong>NoAlias</strong> 最有价值：确认两个指针不冲突，就可以放心重排加载/存储、做向量化。MayAlias 时只能保守处理。</p><h2 id="基于别名图的别名分析" tabindex="-1"><a class="header-anchor" href="#基于别名图的别名分析" aria-hidden="true">#</a> 基于别名图的别名分析</h2><p>指针集合回答「每个指针指向谁」，别名图则直接回答「哪两个指针可能冲突」。每个指针是一个节点，若两个指针的指向集合有交集，就在它们之间连一条边：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>   a   b
   ↑   ↑
   p — q        // p 与 q 都指向 a，存在别名边
   |
   r            // r -&gt; {b}，与 p 无边
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>别名图适合快速查询「与 p 可能冲突的指针有哪些」，在依赖分析、调度优化中很常用。缺点是节点多时边数可能膨胀，因此实际编译器往往结合两种表示：用指针集合做传播，按需构建别名图。</p><h2 id="影响精度的因素" tabindex="-1"><a class="header-anchor" href="#影响精度的因素" aria-hidden="true">#</a> 影响精度的因素</h2><p>别名分析绕不开的难题是精度与速度的权衡：</p><ol><li><strong>流敏感（Flow-Sensitive）</strong>：区分程序点的先后，汇合点做并集——更准，但更慢</li><li><strong>流不敏感（Flow-Insensitive）</strong>：忽略控制流顺序，全局维护一个集合——更快，但更保守</li><li><strong>字段敏感（Field-Sensitive）</strong>：区分结构体的不同成员（<code>p-&gt;x</code> 与 <code>p-&gt;y</code> 不别名）</li><li><strong>字段不敏感（Field-Insensitive）</strong>：把整个对象当作一个单元——<code>p-&gt;x</code> 与 <code>p-&gt;y</code> 被当成可能别名</li><li><strong>上下文敏感（Context-Sensitive）</strong>：区分不同调用路径上的指针状态</li></ol>`,41),u=a(`<h2 id="别名分析如何帮助优化" tabindex="-1"><a class="header-anchor" href="#别名分析如何帮助优化" aria-hidden="true">#</a> 别名分析如何帮助优化</h2><p>回到前面的应用场景，有了别名结果就能具体落地：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">void</span> <span class="token function">foo</span><span class="token punctuation">(</span><span class="token keyword">int</span> <span class="token operator">*</span>p<span class="token punctuation">,</span> <span class="token keyword">int</span> <span class="token operator">*</span>q<span class="token punctuation">,</span> <span class="token keyword">int</span> <span class="token operator">*</span>r<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token operator">*</span>p <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>
    <span class="token keyword">int</span> x <span class="token operator">=</span> <span class="token operator">*</span>q<span class="token punctuation">;</span>   <span class="token comment">// 若 NoAlias(p, q)，x 的加载不受上面写入影响</span>
    <span class="token operator">*</span>r <span class="token operator">=</span> x <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>   <span class="token comment">// 若 NoAlias(q, r)，可消除对 *q 的冗余加载</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>若分析得出 <code>p</code>、<code>q</code>、<code>r</code> 两两 NoAlias，编译器可以：</p><ul><li>将 <code>*p = 1</code> 与 <code>int x = *q</code> <strong>交换顺序</strong>（原本可能因别名不敢动）</li><li>确认 <code>x = *q</code> 只加载一次，不做重复读取</li><li>在循环中安全做<strong>向量化</strong>，因为不同指针不会互相踩内存</li></ul><p>这就是为什么 C 的 <code>restrict</code> 关键字能显著帮助优化——它向编译器承诺「通过此指针的访问不与其他指针别名」，分析器可以直接得到 NoAlias 结论。</p>`,6);function v(k,m){const s=t("RouterLink");return o(),p("div",null,[r,i("p",null,[n("日常编译优化大多采用「流敏感 + 字段敏感」的折中方案；跨函数的完整分析则依赖 "),d(s,{to:"/%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86/2.%E4%B8%AD%E7%AB%AF/(7)%E6%8C%87%E5%90%91%E5%88%86%E6%9E%90.html"},{default:c(()=>[n("指向分析")]),_:1}),n(" 提供指针指向信息，再在此基础上判断别名。")]),u])}const b=e(l,[["render",v],["__file","(6)别名分析.html.vue"]]);export{b as default};
